{"files": [{"path": "creative_intent.json", "content": "{
  "user_need": "概念：1992年，男主是倒爷（个体户），骑嘉陵摩托穿州过省做生意，女主是国营厂下岗女工。他让她坐在后座押货，从南方到北方，七天七夜。她以为是雇佣关系，其实他在进行一场'流浪婚礼'——每经过一个县城就供销社买一对枕巾（内部鸳鸯图案），堆满了摩托车的边斗。最后一天他告诉她'如果这单赚了，我娶你；如果赔了，摩托归你，我归摩托（死在路上）'。结果是赔了，但她把摩托卖了，买了两张去深圳的车票。场景：嘉陵摩托车（移动封闭空间，风雨中的金属茧）；物件：枕巾（商品→聘礼→地图标记，状态：批量→一对→盖在他们头上避雨）；边斗（货仓→婚房→棺材隐喻）；疯点：他在暴风雨中停车，只是为了给她买一顶红丝巾（怕她冷）；她会在经过一个城市时偷偷在地图上画心；最后一夜他们在桥洞下过夜，他把所有枕巾铺开当床，说'现在我们有一万张婚床'；单频振动：漂泊的确定（从雇佣→共谋→定情→新生）；篇幅：6500-10000字",
  "inspiration_state": "clear_inspiration",
  "extracted_elements": {
    "emotion_verbs": ["押送", "流浪", "赌博", "隐瞒", "发现", "选择", "重生"],
    "scene_elements": ["1992年", "嘉陵摩托", "供销社", "枕巾", "暴风雨", "桥洞", "深圳"],
    "relationship_tension": ["雇佣vs求婚", "知情vs不知情", "赌命vs托付", "失去一切vs获得彼此"],
    "user_preferences": {
      "desired_emotion": "漂泊的确定——温暖中带苦涩，最终走向希望",
      "forbidden": ["狗血误会", "第三者", "家庭反对", "身体虐待"]
    }
  },
  "selected_recipe": {
    "x_axis_mode_id": "D22",
    "x_axis_mode_name": "完全献祭",
    "y_axis_tags": ["双向暗恋", "商战权谋"],
    "reaction_strength": "↗",
    "tension_stars": 4,
    "forbidden_elements": ["狗血误会", "第三者介入", "家庭反对", "身体虐待", "出轨", "死亡结局"],
    "x_axis_display": "男主陈大勇以整单生意和生命为赌注，进行一场'流浪婚礼'——七天七夜，每一对枕巾都是无声的求婚。他用最极端的方式献祭一切：货物、摩托、甚至'死在路上'的决心，只为换取一个爱的确定。",
    "y_axis_combination_effect": "双向暗恋制造核心信息差（读者逐渐发现男主的秘密，女主直到最后才知道真相），商战权谋提供时代背景（1992年倒爷与下岗女工，两个被时代抛下的人在旅途中互相认领）。",
    "reaction_formula": "完全献祭 × 双向暗恋 × 商战权谋 → 一场以生意为名的七天婚礼，一次漂泊中的确定",
    "platform_fit": ["番茄小说", "豆瓣阅读", "文学期刊"]
  },
  "one_sentence_synopsis": "1992年，倒爷以七天送货之旅秘密进行'流浪婚礼'，下岗女工在最后一夜才发觉自己早已是新娘。"
}
"}, {"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "陈大勇",
      "role": "男主",
      "traits": ["敢赌敢拼", "嘴硬心软", "浪漫隐秘", "宿命式悲观"],
      "overt_motivation": "把这批货送到北方，赚一笔钱",
      "covert_motivation": "用七天时间完成一场'流浪婚礼'，向周小满求婚",
      "secret_fear": "害怕小满知道真相后拒绝他，害怕自己配不上她，害怕赌输后真的'归摩托'留下她一个人",
      "character_arc": "从独自承担一切的赌徒 → 学会与她共同面对未来"
    },
    {
      "name": "周小满",
      "role": "女主",
      "traits": ["坚韧隐忍", "细心敏感", "口是心非", "渴望安稳"],
      "overt_motivation": "赚七天工钱，补贴家用",
      "covert_motivation": "渴望被需要、被选择，证明自己不只是'下岗的累赘'",
      "secret_fear": "害怕再次失去依靠，害怕自己只是被同情而非被爱",
      "character_arc": "从谨慎自保的雇佣者 → 敢于押上一切的共谋者"
    }
  ],
  "supporting_characters": [],
  "relationship_dynamics": {
    "description": "陈大勇与周小满的关系在七天七夜中经历四次转变：",
    "stages": [
      {
        "stage": "初始",
        "state": "雇佣关系（表面）/ 单向暗恋（实际）",
        "tension": "小满以为是临时工作，大勇早已把她当作新娘"
      },
      {
        "stage": "第一幕末-第二幕",
        "state": "被迫亲近的旅伴",
        "tension": "摩托车上的身体靠近与情感疏离的反差，小满开始察觉异常"
      },
      {
        "stage": "第二幕末",
        "state": "共谋者（小满画心、大勇买丝巾）",
        "tension": "双向暗恋开始萌芽，但都没有说破"
      },
      {
        "stage": "第三幕",
        "state": "生死相托的伴侣",
        "tension": "真相揭晓后的共同抉择——不是'你或摩托'，而是'我们一起'"
      }
    ],
    "turning_points": [
      "第一幕转折：小满发现边斗里的枕巾越来越多，开始怀疑这趟旅程不只是送货",
      "第二幕转折：暴风雨中买红丝巾，两人在桥洞下第一次真正意义上的'共同过夜'",
      "第三幕转折：大勇说出'如果赔了，我归摩托'，小满明白这不是雇佣，是一场以命相赌的求婚"
    ]
  }
}
"}, {"path": "outline.json", "content": "{
  "act_one": {
    "story_synopsis": "1992年深秋，下岗女工周小满在劳务市场被倒爷陈大勇以'一天十块，包吃住'的价钱雇为押货人。她不知道的是，这趟从广州到郑州的七天旅程，是他筹划已久的'流浪婚礼'。第一幕从他们出发开始：小满坐在嘉陵摩托后座，双手不得不环住大勇的腰，这种身体接触让她不自在；大勇每经过一个县城就找借口去供销社，买回一对内部鸳鸯图案的枕巾，塞进边斗。小满注意到边斗里的枕巾越来越多，但大勇说是'给客户带的样品'。第一幕在小满第一次偷偷在地图画心时达到转折——她开始期待这趟旅程，却不知道期待的是什么。",
    "turning_point": "小满在地图上画下第一个心形，意识到自己不再把这当作单纯的雇佣，而是开始期待明天的旅程。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "title": "边斗里的秘密",
        "chapter_synopsis": "小满在劳务市场被大勇雇佣，第一次坐上嘉陵摩托后座。她拘谨地保持身体距离，大勇则故意骑得颠簸让她不得不抱住他。当晚他们在县城旅馆住下，小满发现大勇去供销社买了一对枕巾，说是'样品'。她开始注意到边斗里的货物中，枕巾的数量在神秘增加。",
        "scene_sequence": [
          {
            "scene_number": 1,
            "scene_location": "广州劳务市场，1992年深秋傍晚，人声嘈杂",
            "characters_present": ["陈大勇", "周小满"],
            "scene_purpose": "建立雇佣关系，展示两人初次相遇的状态",
            "core_action": "大勇在劳务市场打量一圈，走向角落里的小满，问她'会骑摩托吗'，小满摇头，他说'那正好，我要个押货的'",
            "conflict_point": "小满犹豫是否跟一个陌生男人走七天，大勇看出她的顾虑，把身份证和工作证拍在桌上说'我不是人贩子'",
            "emotional_shift": "从戒备犹豫 → 被十块钱一天的工钱打动，决定冒险",
            "scene_outcome": "小满同意上路，两人第一次走向嘉陵摩托，埋下'旅程开始'的伏笔"
          },
          {
            "scene_number": 2,
            "scene_location": "国道，黄昏，摩托行驶中",
            "characters_present": ["陈大勇", "周小满"],
            "scene_purpose": "建立摩托车上的身体关系，制造被迫亲近的张力",
            "core_action": "大勇故意在有坑的路面加速，小满被颠得不得不抱住他的腰，脸贴在他后背上闻到肥皂和机油的味道",
            "conflict_point": "小满想松开手保持体面，但下一个颠簸让她抓得更紧",
            "emotional_shift": "从尴尬拘谨 → 微妙的身体接触带来的心跳加速",
            "scene_outcome": "天黑前他们到达第一个县城，小满的双腿发麻，大勇伸手拉她下车，两人第一次有意识的肢体接触"
          },
          {
            "scene_number": 3,
            "scene_location": "县城供销社和旅馆，夜晚",
            "characters_present": ["陈大勇", "周小满", "供销社店员"],
            "scene_purpose": "揭示第一个'疯点'——买枕巾，建立信息差",
            "core_action": "大勇让小满在旅馆收拾，自己去了供销社，用内部关系买到一对鸳鸯图案枕巾，偷偷塞进边斗的货物下面",
            "conflict_point": "小满从窗户看到大勇拿着枕巾回来，疑惑为什么是'枕巾'而不是其他货物",
            "emotional_shift": "从疲惫 → 好奇，开始注意这个男人的异常",
            "scene_outcome": "小满发现边斗里多了枕巾，大勇说是'给客户的样品'，小满将信将疑，第一幕结束"
          }
        ]
      }
    ]
  },
  "act_two": {
    "story_synopsis": "第二幕是旅途中的四天，两人从陌生到熟悉，从雇佣关系到暧昧共谋。小满开始习惯摩托车的颠簸，也习惯了自己的双手环住大勇的腰。她注意到边斗里的枕巾每天都在增加——第二天两对，第三天三对，第四天四对。她偷偷在地图册上画心形标记他们经过的每个城市。大勇在第四天遭遇暴风雨，他在暴雨中停车冲进供销社，只为给小满买一条红丝巾御寒。当晚他们被迫在桥洞下过夜，大勇把所有枕巾铺在地上当床，说'现在我们有一万张婚床'。小满以为他在开玩笑，但那一刻她第一次想要靠近他。第二幕在她主动把红丝巾系在大勇脖子上时达到转折——她开始主动表达情感。",
    "turning_point": "暴风雨之夜，小满主动把红丝巾系在大勇脖子上，两人第一次真正意义上的'共同过夜'，她从被动接受者变成主动参与者。",
    "key_chapters": [
      {
        "chapter_number": 2,
        "title": "一万张婚床",
        "chapter_synopsis": "旅途第四天，他们在路上遭遇暴风雨。大勇在暴雨中停车冲进供销社，只为给小满买一条红丝巾。当晚被迫在桥洞下过夜，大勇把所有枕巾铺在地上，说出'一万张婚床'的话。小满在火光中第一次认真看他的脸，发现这个倒爷有一双过分温柔的眼睛。",
        "scene_sequence": [
          {
            "scene_number": 1,
            "scene_location": "国道，暴雨中，摩托艰难行驶",
            "characters_present": ["陈大勇", "周小满"],
            "scene_purpose": "制造'暴风雨中买丝巾'的疯点，展示大勇的细心",
            "core_action": "暴雨中大勇突然停车，让小满在桥下等着，自己冲进雨幕中的供销社，用身上最后的零钱买下一条红丝巾",
            "conflict_point": "小满在雨中发抖，不知道他为什么突然离开，怀疑他要抛下她",
            "emotional_shift": "从恐惧被抛弃 → 看到红丝巾时的震惊和感动",
            "scene_outcome": "大勇把丝巾裹在她头上说'别感冒了，还要押货呢'，小满第一次意识到这个男人的关心超出雇佣关系"
          },
          {
            "scene_number": 2,
            "scene_location": "桥洞下，夜晚，火堆旁",
            "characters_present": ["陈大勇", "周小满"],
            "scene_purpose": "核心场景——'一万张婚床'，情感升温的关键节点",
            "core_action": "大勇从边斗里搬出所有枕巾，一对对铺在地上，堆成一张柔软的'床'，小满数了数已经有十对",
            "conflict_point": "小满问'为什么要买这么多枕巾'，大勇看着她说'现在我们有一万张婚床'，既像玩笑又像告白",
            "emotional_shift": "从困惑 → 心跳漏拍，意识到这不是玩笑",
            "scene_outcome": "两人躺在枕巾上，隔着火光对视，小满第一次主动把红丝巾系在大勇脖子上，说'你也别感冒'"
          },
          {
            "scene_number": 3,
            "scene_location": "桥洞下，深夜",
            "characters_present": ["陈大勇", "周小满"],
            "scene_purpose": "展示两人关系转折后的状态，为第三幕做铺垫",
            "core_action": "小满假装睡着，头靠在大勇肩上，大勇一动不动怕惊醒她，两人听着雨声和彼此的呼吸",
            "conflict_point": "小满在黑暗中偷偷数枕巾的数量，十一对，足够铺满一张真正的婚床",
            "emotional_shift": "从暧昧 → 确定，她开始期待这趟旅程的终点",
            "scene_outcome": "天亮前小满在地图册上画下第四颗心，大勇假装没看见，但嘴角翘了起来，第二幕结束"
          }
        ]
      }
    ]
  },
  "act_three": {
    "story_synopsis": "第三幕是最后两天的冲刺和真相揭晓。第五天和第六天，两人几乎不休息地赶路，小满知道终点近了，却不知道等待她的是什么。大勇越来越沉默，因为郑州的买家出了变故——货可能卖不出去，他的赌注可能要输了。第七天夜里，他们在郑州郊外的空地上，大勇终于说出真相：这不是雇佣，是一场流浪婚礼，如果货赚了他就娶她，如果赔了，摩托归她，他'归摩托'（死在路上）。小满这才知道那些枕巾是聘礼，这趟旅程是求婚。结果是货真的赔了，大勇沉默地准备履行诺言，但小满把摩托卖了，买了两张去深圳的车票。她说'你归我了'。第三幕在两人坐上南下的火车时达到新稳态——他们不是谁赢了谁，而是共同选择了漂泊中的确定。",
