          {
            "scene_number": 2,
            "scene_location": "郑州火车站，凌晨",
            "characters_present": ["陈大勇", "周小满", "摩托买家"],
            "scene_purpose": "小满的选择——从被动到主动",
            "core_action": "小满当街拦住一个想买摩托的人，把嘉陵摩托卖了八百块，转身买了两张去深圳的车票",
            "conflict_point": "大勇想阻止她，说'你不欠我的'，小满把票拍在他胸口说'你归我了'",
            "emotional_shift": "从绝望 → 新生的希望",
            "scene_outcome": "两人站在检票口，小满把最后一对枕巾盖在两人头上避雨，说'现在我们有一万零一对婚床'"
          },
          {
            "scene_number": 3,
            "scene_location": "南下的火车，黎明",
            "characters_present": ["陈大勇", "周小满"],
            "scene_purpose": "新稳态定格，物件回扣封蜡",
            "core_action": "两人坐在硬座上，头靠在一起，枕巾铺在他们头顶的行李架上，像一顶真正的盖头。火车穿过隧道，黑暗中有笑声",
            "conflict_point": "无",
            "emotional_shift": "从漂泊 → 确定",
            "scene_outcome": "故事结束在火车驶出隧道，阳光洒进来的瞬间"
          }
        ]
      }
    ]
  }
